tool_input.command:
cd /workspaces/semio && node -e "
const fs = require('fs');
const html = fs.readFileSync('semio/engine/dist/mcp-app.html', 'utf8');

// Extract the script content from the single-file HTML
const match = html.match(/<script type=\"module\">([\s\S]*?)<\/script>/);
if (!match) {
  console.log('No script tag found');
  process.exit(1);
}
const script = match[1];

// Check for obvious issues
console.log('Script size:', script.length, 'chars');

// Check for imports that wouldn't work inlined
const imports = script.match(/\\bimport\\s+/g);
console.log('Import statements:', imports?.length ?? 0);

// Check if there are any remaining external module imports 
const externalImports = script.match(/from\\s*['\"]([^'\"]+)['\"]/g);
if (externalImports) {
  console.log('External imports found:', externalImports);
} else {
  console.log('No external imports - fully inlined');
}

// Check for 'use strict' / module issues 
const hasUseStrict = script.includes('use strict');
console.log('Has use strict:', hasUseStrict);

// Check for postMessage
const hasPostMessage = script.includes('postMessage');
console.log('Has postMessage:', hasPostMessage);

// Check for window.parent
const hasWindowParent = script.includes('window.parent');
console.log('Has window.parent:', hasWindowParent);

// Check for getElementById
const hasGetElementById = script.includes('getElementById');
console.log('Has getElementById:', hasGetElementById);
"

